def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    # Start with absolute path
    if path.startswith('/'):
        current = ''  # represents root
    else:
        current = cwd

    # Split path into components
    components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]
        i += 1

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current == '':
                # Already at root, stay at root
                pass
            else:
                # Move to parent
                last_slash = current.rfind('/')
                if last_slash == -1:
                    current = ''
                else:
                    current = current[:last_slash]
            continue

        # Append the component to current path
        if current == '':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > max_links:
                return None

            # Get the symlink target
            target = links[current]

            # Resolve the target
            if target.startswith('/'):
                # Absolute symlink target
                current = ''
                target_components = target.split('/')
            else:
                # Relative symlink target - relative to directory containing the link
                last_slash = current.rfind('/')
                if last_slash == -1:
                    # This shouldn't happen for a canonical path
                    return None
                current = current[:last_slash]
                target_components = target.split('/')

            # Insert remaining components after target components
            remaining_components = components[i:]
            components = target_components + remaining_components
            i = 0

    # Return the result
    if current == '':
        return '/'
    else:
        return current

